type EdgeReq = {
  body: Record<string, unknown>;
  query: Record<string, unknown>;
  params: Record<string, string>;
  method: string;
  headers: Record<string, string | undefined>;
};

type EdgeRes = {
  json: (data: unknown) => unknown;
  send: (data: unknown) => unknown;
  status: (code: number) => EdgeRes;
};

const edgeReq = req as EdgeReq;
const edgeRes = res as EdgeRes;

const toNumber = (value: unknown): number | null => {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
};

async function handler(): Promise<void> {
  const body = edgeReq.body && typeof edgeReq.body === 'object' ? edgeReq.body : {};
  const a = toNumber(body.a);
  const b = toNumber(body.b);

  if (a === null || b === null) {
    edgeRes.status(400).json({
      success: false,
      error: 'Request body must include numeric fields "a" and "b".',
    });
    return;
  }

  edgeRes.json({
    success: true,
    data: {
      sum: a + b,
    },
  });
}

(async () => {
  await handler();
})();

