1|import { createHash } from 'crypto';
2|import type { AgentMode, ChangeSet, ProposalViolation } from '../../../shared/api/contracts/ai/agentTypes';
3|import type { AiAgentSettings } from '../../../shared/api/contracts/ai/types';
4|import type { AiPageContext } from '../../../shared/api/contracts/ai/pageContext';
5|import { isAllowlistedPath, isPlanModeDocumentPath } from '../tools/pathAllowlist';
6|import { validateChangeSetsAgainstStandards } from './standardsProposalValidator';
7|import {
8|  normalizeSandboxSource,
9|  sandboxSourceUsesUnsupportedModulePattern,
10|} from '../../../shared/server-functions/sandboxSourceNormalize';
11|
12|const SECRET_PATTERNS: RegExp[] = [
13|  /(?:api[_-]?key|secret|token|password|authorization)\s*[:=]\s*['"]?[A-Za-z0-9_\-./+=]{8,}/i,
14|  /sk-[A-Za-z0-9]{16,}/,
15|  /Bearer\s+[A-Za-z0-9._\-+/=]{20,}/i,
16|];
17|
18|export type ProposalValidationOptions = {
19|  mode?: AgentMode;
20|  agentSettings?: AiAgentSettings;
21|  userIntentPaths?: string[];
22|  pageContext?: AiPageContext;
23|};
24|
25|export type ProposalValidationResult = {
26|  ok: boolean;
27|  violations: ProposalViolation[];
28|};
29|
30|const countChangedLines = (before: string | undefined, after: string): number => {
31|  if (!before) return after.split(/\r?\n/).length;
32|  const beforeLines = before.split(/\r?\n/);
33|  const afterLines = after.split(/\r?\n/);
34|  const max = Math.max(beforeLines.length, afterLines.length);
35|  let changed = 0;
36|  for (let index = 0; index < max; index += 1) {
37|    if ((beforeLines[index] ?? '') !== (afterLines[index] ?? '')) {
38|      changed += 1;
39|    }
40|  }
41|  return changed;
42|};
43|
44|const extractSearchableText = (changeSet: ChangeSet): string => {
45|  switch (changeSet.kind) {
46|    case 'file_patch':
47|      return changeSet.content;
48|    case 'component_layout_patch':
49|      return JSON.stringify(changeSet.patch ?? {});
50|    case 'function_source_patch':
51|      return JSON.stringify(changeSet.patch ?? {});
52|    case 'settings_block_patch':
53|      return JSON.stringify(changeSet.patch ?? {});
54|    case 'git_operation':
55|      return JSON.stringify({
56|        operation: changeSet.operation,
57|        message: changeSet.message,
58|        target: changeSet.target,
59|        branchName: changeSet.branchName,
60|      });
61|    default:
62|      return '';
63|  }
64|};
65|
66|const extractPath = (changeSet: ChangeSet): string | undefined => {
67|  if (changeSet.kind === 'file_patch') return changeSet.path;
68|  if (changeSet.kind === 'component_layout_patch') return `component-designer:${changeSet.layoutId}`;
69|  if (changeSet.kind === 'function_source_patch') return `edge-function:${changeSet.functionId}`;
70|  if (changeSet.kind === 'settings_block_patch') return `settings:${changeSet.blockKey}`;
71|  if (changeSet.kind === 'git_operation') return `git:${changeSet.operation}`;
72|  return undefined;
73|};
74|
75|export const validateProposal = (
76|  changeSets: ChangeSet[],
77|  options: ProposalValidationOptions = {},
78|): ProposalValidationResult => {
79|  const violations: ProposalViolation[] = [];
80|  const maxFiles = options.agentSettings?.vibeMaxFilesPerProposal ?? 8;
81|  const maxLines = options.agentSettings?.vibeMaxLinesPerProposal ?? 400;
82|  const userIntentPaths = new Set(options.userIntentPaths ?? []);
83|
84|  if (changeSets.length === 0) {
85|    violations.push({
86|      id: 'empty-proposal',
87|      severity: 'error',
88|      message: 'Proposal contains no change sets.',
89|    });
90|    return { ok: false, violations };
91|  }
92|
93|  if (changeSets.length > maxFiles) {
94|    violations.push({
95|      id: 'surface-max-files',
96|      severity: 'error',
97|      message: `Proposal touches ${changeSets.length} files/components; limit is ${maxFiles}.`,
98|    });
99|  }
100|
101|  let totalLines = 0;
102|
103|  changeSets.forEach((changeSet) => {
104|    const path = extractPath(changeSet);
105|
106|    if (options.mode === 'plan') {
107|      if (changeSet.kind !== 'file_patch') {
108|        violations.push({
109|          id: `plan-scope-${changeSet.id}`,
110|          severity: 'error',
111|          message: `Plan mode only allows markdown file patches under plans/core/ or plans/packages/ (got ${changeSet.kind}).`,
112|          changeSetId: changeSet.id,
113|        });
114|        return;
115|      }
116|
117|      if (!isPlanModeDocumentPath(changeSet.path)) {
118|        violations.push({
119|          id: `plan-path-${changeSet.id}`,
120|          severity: 'error',
121|          message: `Plan mode path "${changeSet.path}" must be a .md file under plans/core/ or plans/packages/.`,
122|          changeSetId: changeSet.id,
123|        });
124|      }
125|    }
126|
127|    if (changeSet.kind === 'file_patch') {
128|      if (!isAllowlistedPath(changeSet.path)) {
129|        violations.push({
130|          id: `path-${changeSet.id}`,
131|          severity: 'error',
132|          message: `Path "${changeSet.path}" is outside the agent allowlist.`,
133|          changeSetId: changeSet.id,
134|        });
135|      }
136|
137|      const lineCount = changeSet.content.split(/\r?\n/).length;
138|      totalLines += lineCount;
139|
140|      if (changeSet.beforeHash && changeSet.content) {
141|        const beforeLineEstimate = Math.max(1, Math.floor(lineCount * 0.2));
142|        const changedEstimate = countChangedLines(undefined, changeSet.content);
143|        if (changedEstimate / Math.max(lineCount, 1) > 0.8 && lineCount > 20) {
144|          violations.push({
145|            id: `rewrite-${changeSet.id}`,
146|            severity: 'warning',
147|            message: `Large rewrite detected for ${changeSet.path} (>80% lines changed). Confirm explicitly if intended.`,
148|            changeSetId: changeSet.id,
149|          });
150|        }
151|        void beforeLineEstimate;
152|      }
153|    } else if (changeSet.kind === 'component_layout_patch') {
154|      totalLines += Math.max(1, Math.ceil(JSON.stringify(changeSet.patch ?? {}).length / 80));
155|    } else if (changeSet.kind === 'function_source_patch') {
156|      totalLines += Math.max(1, Math.ceil(JSON.stringify(changeSet.patch ?? {}).length / 80));
157|      const patch = changeSet.patch && typeof changeSet.patch === 'object' && !Array.isArray(changeSet.patch)
158|        ? changeSet.patch as Record<string, unknown>
159|        : {};
160|      const source = typeof patch.source === 'string' ? patch.source : '';
161|      const normalizedSource = normalizeSandboxSource(source);
162|      if (sandboxSourceUsesUnsupportedModulePattern(normalizedSource)) {
163|        violations.push({
164|          id: `function-sandbox-pattern-${changeSet.id}`,
165|          severity: 'error',
166|          message: 'Server function source must use the AppEndO sandbox pattern (global req/res + async function handler) — not export default or module.exports.',
167|          changeSetId: changeSet.id,
168|          ruleId: 'server-functions.sandbox-source',
169|        });
170|      }
171|      const openFunctionId = options.pageContext?.functionId?.trim();
172|      const patchOperation = typeof patch.operation === 'string' ? patch.operation.trim() : undefined;
173|      const baseFunctionId = typeof patch.baseFunctionId === 'string' ? patch.baseFunctionId.trim() : undefined;
174|      const claimsOpenFunctionUpdate = patchOperation === 'update' || baseFunctionId === openFunctionId;
175|      if (
176|        openFunctionId
177|        && changeSet.functionId !== openFunctionId
178|        && claimsOpenFunctionUpdate
179|      ) {
180|        violations.push({
181|          id: `function-identity-mismatch-${changeSet.id}`,
182|          severity: 'error',
183|          message: `Open function is "${openFunctionId}" but proposal targets "${changeSet.functionId}". Use operation "update" with functionId "${openFunctionId}".`,
184|          changeSetId: changeSet.id,
185|          ruleId: 'ai.vibe.server-function-identity',
186|        });
187|      }
188|    } else if (changeSet.kind === 'git_operation') {
189|      totalLines += 1;
190|      if (changeSet.operation === 'checkout' && changeSet.target) {
191|        const target = changeSet.target.toLowerCase();
192|        if (target === 'main' || target === 'master') {
193|          violations.push({
194|            id: `git-protected-${changeSet.id}`,
195|            severity: 'warning',
196|            message: `Checkout to protected branch "${changeSet.target}" — confirm explicitly if intended.`,
197|            changeSetId: changeSet.id,
198|          });
199|        }
200|      }
201|      if (changeSet.operation === 'branch' && changeSet.branchName) {
202|        const branch = changeSet.branchName.toLowerCase();
203|        if (branch === 'main' || branch === 'master') {
204|          violations.push({
205|            id: `git-protected-branch-${changeSet.id}`,
206|            severity: 'warning',
207|            message: `Creating branch named "${changeSet.branchName}" may be unintended — confirm explicitly.`,
208|            changeSetId: changeSet.id,
209|          });
210|        }
211|      }
212|      if (changeSet.operation === 'commit' && !changeSet.message?.trim()) {
213|        violations.push({
214|          id: `git-commit-message-${changeSet.id}`,
215|          severity: 'error',
216|          message: 'Git commit requires a non-empty message.',
217|          changeSetId: changeSet.id,
218|        });
219|      }
220|    } else {
221|      totalLines += Math.max(1, Math.ceil(extractSearchableText(changeSet).length / 80));
222|    }
223|
224|    const searchable = extractSearchableText(changeSet);
225|    SECRET_PATTERNS.forEach((pattern, index) => {
226|      if (pattern.test(searchable)) {
227|        violations.push({
228|          id: `secret-${changeSet.id}-${index}`,
229|          severity: 'error',
230|          message: `Possible secret/credential pattern detected in "${changeSet.title}".`,
231|          changeSetId: changeSet.id,
232|        });
233|      }
234|    });
235|
236|    if (path && userIntentPaths.size > 0 && changeSet.kind === 'file_patch') {
237|      const matchesIntent = [...userIntentPaths].some((intentPath) => (
238|        changeSet.path.includes(intentPath) || intentPath.includes(changeSet.path)
239|      ));
240|      if (!matchesIntent) {
241|        violations.push({
242|          id: `unrelated-${changeSet.id}`,
243|          severity: 'warning',
244|          message: `File "${changeSet.path}" was not mentioned in the plan surface estimate.`,
245|          changeSetId: changeSet.id,
246|        });
247|      }
248|    }
249|  });
250|
251|  if (totalLines > maxLines) {
252|    violations.push({
253|      id: 'surface-max-lines',
254|      severity: 'error',
255|      message: `Estimated changed lines (${totalLines}) exceed limit of ${maxLines}.`,
256|    });
257|  }
258|
259|  if (options.mode !== 'plan') {
260|    violations.push(...validateChangeSetsAgainstStandards(changeSets));
261|  }
262|
263|  const hasErrors = violations.some((violation) => violation.severity === 'error');
264|  return { ok: !hasErrors, violations };
265|};
