13|export function isDesignerDocument(value: unknown): value is DesignerDocument {
14|  if (!isRecord(value)) {
15|    return false;
16|  }
17|  const rootNodeId = typeof value.rootNodeId === 'string' ? value.rootNodeId.trim() : '';
18|  const nodes = isRecord(value.nodes) ? value.nodes : null;
19|  if (!rootNodeId || !nodes || !isRecord(nodes[rootNodeId])) {
