40|  args: Record<string, unknown>,
41|): ClientComponentLayoutApplyPayload | null {
42|  if (!isDesignerDocument(args.document)) {
43|    return null;
44|  }
45|  const bindingDefinitions = isRecord(args.bindingDefinitions)
46|    ? args.bindingDefinitions as DesignerBindingDefinitions
47|    : {};
