51|export type ClientComponentAgentApplyCollector = {
52|  ingest: (event: AgentStreamEvent) => void;
53|  layout: () => ClientComponentLayoutApplyPayload | null;
54|};
55|
56|/** Latest drafted layout from a proposal, or from draft_component_layout tool args. */
57|export function createClientComponentAgentApplyCollector(): ClientComponentAgentApplyCollector {
58|  let proposalLayout: ClientComponentLayoutApplyPayload | null = null;
59|  let draftToolLayout: ClientComponentLayoutApplyPayload | null = null;
60|
61|  return {
62|    ingest(event) {
63|      if (event.type === 'proposal') {
64|        const layouts = event.changeSets.map(readLayoutFromComponentPatch).filter(
65|          (layout): layout is ClientComponentLayoutApplyPayload => Boolean(layout),
66|        );
67|        if (layouts.length > 0) {
68|          proposalLayout = layouts[layouts.length - 1] ?? null;
69|        }
70|        return;
71|      }
72|      if (event.type === 'tool_start' && event.name === 'draft_component_layout') {
